### 2. Chat Manager - Add Mark Seen Method

```py codx/junior/chat_manager.py
    def mark_message_as_seen(self, chat: Chat, message_doc_id: str, username: str) -> Chat:
        """
        Mark a message as seen by a user (merge-safe).

        Updates the message's seen_by list with the username, respecting any
        concurrent updates by merging against the stored chat first.

        :param chat: The chat containing the message.
        :param message_doc_id: The doc_id of the message to mark as seen.
        :param username: The username of the user who saw the message.
        :return: The persisted chat with updated message.
        """
        if not message_doc_id or not username:
            logger.error("mark_message_as_seen: missing message_doc_id or username")
            return chat

        manager = self._resolve_owner_manager(chat)
        stored_chat = manager._load_stored_chat(chat)

        # Merge message lists to respect concurrent updates
        if stored_chat:
            chat.messages = self._merge_message_lists(
                stored_messages=stored_chat.messages,
                incoming_messages=chat.messages,
            )

        # Find and update the message
        for message in chat.messages:
            if message.doc_id == message_doc_id:
                # Initialize seen_by if needed
                if not message.seen_by:
                    message.seen_by = []
                # Add username if not already present
                if username not in message.seen_by:
                    message.seen_by.append(username)
                message.updated_at = datetime.now().isoformat()
                logger.info(
                    "mark_message_as_seen: chat='%s' message='%s' user='%s' seen_by=%s",
                    chat.id,
                    message_doc_id,
                    username,
                    message.seen_by,
                )
                break

        return manager.save_chat(chat=chat)
