### 3. API Endpoint - Add Mark Seen Endpoint

```py codx/junior/api/chat.py
@router.post("/chats/mark-seen")
async def api_mark_message_as_seen(request: Request):
    """
    Mark a message as seen by a user.

    Expected JSON payload:
        {
            "chat_id": "<chat UUID or doc_id>",
            "message_id": "<message doc_id>",
            "username": "<username>"
        }

    Returns:
        The updated Chat object with the message's seen_by list updated.
    """
    try:
        data = await request.json()
        codx_junior_session = request.state.codx_junior_session
        chat_manager = codx_junior_session.get_chat_manager()

        chat_id = data.get("chat_id")
        message_id = data.get("message_id")
        username = data.get("username")

        if not chat_id or not message_id or not username:
            logger.error(
                "api_mark_message_as_seen: missing required fields - chat_id=%s message_id=%s username=%s",
                chat_id,
                message_id,
                username,
            )
            return {"error": "missing chat_id, message_id, or username"}

        chat = chat_manager.find_by_id(chat_id=chat_id)
        if not chat:
            logger.error("api_mark_message_as_seen: chat not found: %s", chat_id)
            return {"error": f"chat '{chat_id}' not found"}

        updated_chat = chat_manager.mark_message_as_seen(
            chat=chat,
            message_doc_id=message_id,
            username=username,
        )

        return updated_chat
    except Exception as ex:
        logger.error("api_mark_message_as_seen: unexpected error: %s", ex)
        return {"error": f"Failed to mark message as seen: {str(ex)}"}
