    async submitMessageSeen() {
      try {
        const currentUsername = this.$user?.username
        if (!currentUsername) return
        const seenByList = this.message.seen_by || []
        if (seenByList.includes(currentUsername)) {
          this.hasSeen = true
          return
        }
        await this.$storex.api.chats.markMessageAsSeen({
          chat_id: this.chat?.id,
          message_id: this.message?.doc_id,
          username: currentUsername
        })
        this.hasSeen = true
        this.message.seen_by = [...(this.message.seen_by || []), currentUsername]
      } catch (ex) {
        console.error('Failed to mark message as seen', ex)
      }
    },
